import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { useCart } from '../context/CartContext';
import { 
  HomeIcon, 
  ShoppingBagIcon, 
  ShoppingCartIcon, 
  UserIcon,
  Bars3Icon,
  XMarkIcon
} from '@heroicons/react/24/outline';

const Navbar = () => {
  const { user, logout } = useAuth();
  const { getTotalItems } = useCart();
  const navigate = useNavigate();
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const isFarmer = user?.userType === "farmer";
  const isCustomer = user?.userType === "customer";

  const handleLogout = () => {
    logout();
    localStorage.removeItem("token"); // 🔥 important
    navigate('/');
    setIsMenuOpen(false);
  };

  const NavLink = ({ to, children, onClick }) => (
    <Link
      to={to}
      onClick={onClick}
      className="block text-gray-700 hover:text-green-600 px-3 py-2 rounded-md text-sm font-medium"
    >
      {children}
    </Link>
  );

  return (
    <nav className="bg-white shadow-lg sticky top-0 z-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">

        {/* TOP BAR */}
        <div className="flex justify-between h-16 items-center">

          {/* LOGO */}
          <Link to="/" className="flex items-center space-x-2">
            <div className="w-8 h-8 bg-green-600 rounded-full flex items-center justify-center">
              <span className="text-white font-bold text-sm">F2H</span>
            </div>
            <span className="text-xl font-bold text-green-600">Farm2Home</span>
          </Link>

          {/* DESKTOP NAV */}
          <div className="hidden md:flex items-center space-x-4">

            {/* CUSTOMER NAV */}
            {isCustomer && (
              <>
                <NavLink to="/">
                  <HomeIcon className="w-5 h-5 inline mr-1" />
                  Home
                </NavLink>

                <NavLink to="/marketplace">
                  <ShoppingBagIcon className="w-5 h-5 inline mr-1" />
                  Marketplace
                </NavLink>

                <NavLink to="/cart">
                  <div className="relative inline-block">
                    <ShoppingCartIcon className="w-5 h-5 inline mr-1" />
                    Cart
                    {getTotalItems() > 0 && (
                      <span className="absolute -top-2 -right-2 bg-red-500 text-white text-xs rounded-full h-5 w-5 flex items-center justify-center">
                        {getTotalItems()}
                      </span>
                    )}
                  </div>
                </NavLink>
              </>
            )}

            {/* FARMER NAV */}
            {isFarmer && (
              <NavLink to="/farmer-dashboard">
                Dashboard
              </NavLink>
            )}

            {/* COMMON (LOGGED IN) */}
            {user && (
              <>
                <NavLink to="/profile">
                  <UserIcon className="w-5 h-5 inline mr-1" />
                  Profile
                </NavLink>

                <button
                  onClick={handleLogout}
                  className="bg-red-500 hover:bg-red-600 text-white px-4 py-2 rounded-md text-sm"
                >
                  Logout
                </button>
              </>
            )}

            {/* NOT LOGGED IN */}
            {!user && (
              <>
                <NavLink to="/login">Login</NavLink>
                <Link
                  to="/register"
                  className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-md text-sm"
                >
                  Register
                </Link>
              </>
            )}
          </div>

          {/* MOBILE MENU BUTTON */}
          <div className="md:hidden">
            <button
              onClick={() => setIsMenuOpen(!isMenuOpen)}
            >
              {isMenuOpen ? (
                <XMarkIcon className="w-6 h-6" />
              ) : (
                <Bars3Icon className="w-6 h-6" />
              )}
            </button>
          </div>

        </div>

        {/* MOBILE NAV */}
        {isMenuOpen && (
          <div className="md:hidden border-t mt-2">

            {/* CUSTOMER */}
            {isCustomer && (
              <>
                <NavLink to="/" onClick={() => setIsMenuOpen(false)}>
                  Home
                </NavLink>

                <NavLink to="/marketplace" onClick={() => setIsMenuOpen(false)}>
                  Marketplace
                </NavLink>

                <NavLink to="/cart" onClick={() => setIsMenuOpen(false)}>
                  Cart ({getTotalItems()})
                </NavLink>
              </>
            )}

            {/* FARMER */}
            {isFarmer && (
              <NavLink to="/farmer-dashboard" onClick={() => setIsMenuOpen(false)}>
                Dashboard
              </NavLink>
            )}

            {/* COMMON */}
            {user && (
              <>
                <NavLink to="/profile" onClick={() => setIsMenuOpen(false)}>
                  Profile
                </NavLink>

                <button
                  onClick={handleLogout}
                  className="block w-full text-left text-red-600 px-3 py-2"
                >
                  Logout
                </button>
              </>
            )}

            {/* NOT LOGGED */}
            {!user && (
              <>
                <NavLink to="/login" onClick={() => setIsMenuOpen(false)}>
                  Login
                </NavLink>

                <NavLink to="/register" onClick={() => setIsMenuOpen(false)}>
                  Register
                </NavLink>
              </>
            )}

          </div>
        )}
      </div>
    </nav>
  );
};

export default Navbar;
